Rules.InvariantScript:
App.Height
// THE COMPONENT COVERS THE APP, and the instance can still override it.
// App.Height is the one height in this file that is not derived from
// anything inside the dialog, which is what makes it safe to cap
// against.

Set(_cmpFinishOutcome, "");
Set(_cmpFinishComment, "")
// RESET ON CLOSE, NOT ON OPEN. A canvas component has no lifecycle
// events at all: no OnVisible, no OnHidden, no OnStart. Reset() is the
// only hook and something outside has to call it.
//
// The screen calls it on both close paths, which it is already writing,
// so this costs nothing extra. Closing rather than opening also fails
// better: forget it and the FIRST open is still correct and only a
// second one is stale, which someone notices. Reset on open fails
// silently on the very first use.

cmpDetFinish.OnCancel()
// RAISES THE EVENT, does not set state. The component does not
// know what flag the screen uses to open it, and does not need
// to. Everything the screen owns stays on the screen.

Max(nfSpace.Xl, (Parent.Height - Self.Height) / 2)
// Max, SO CENTRING CANNOT GO NEGATIVE. Once the panel is taller
// than the space it has, it pins to the top with a margin
// instead of hanging off it. Unbounded centring is what put the
// footer buttons below the bottom edge.

conFinHeader.Height
+ conFinBody.Height
+ conFinFooter.Height
// A PLAIN SUM OF THE THREE BANDS, and not one of them reads back
// up to this control. An earlier version capped this with
// Min(sum, Parent.Height - ...) while the body capped itself
// against this panel, which is a straight cycle and Studio
// rejects it: "a property cannot reference itself or other
// properties affected by its value".
//
// The cap belongs on the body, against App.Height, which nothing
// in this dialog can influence.

"Close without completing the task"
// THE ONLY LABEL AN ICON ONLY BUTTON HAS. Tooltip is
// read by the screen reader on Classic/Button, so it has
// to say what the control does, not what it looks like.
// "Close" was not enough.

Min(
    conFinTask.Height + conFinOutcome.Height + conFinComment.Height + 2 * Self.LayoutGap + Self.PaddingTop + Self.PaddingBottom,
    App.Height - conFinHeader.Height - conFinFooter.Height - 4 * nfSpace.Xl
)
// THE BODY IS THE PART THAT SCROLLS. Header and footer are
// fixed bands, so the confirm button is always reachable no
// matter how tall the content gets or how short the viewport
// is. This is the behaviour every dialog should have had from
// the start; without it a phone user cannot reach Cancel.

With(
    { a: LookUp(colAssignments, AssignmentKey = cmpDetFinish.AssignmentKey) },
    a.AssigneeName
    & "   •   "
    & LookUp(nfDepartments, ConfigKey = a.DepartmentCode).Title
)
// READS THE COLLECTIONS DIRECTLY, which is what
// AccessAppScope true buys. The alternative is eight more
// input properties carrying values the component could
// look up itself, and eight more chances for the screen
// and the dialog to disagree about the same task.
//
// AssignmentKey is qualified with the component name
// because the record scope of LookUp also has a column
// called AssignmentKey. Unqualified, the input property
// would be shadowed and the LookUp would compare the
// column to itself and match every row.

Set(_cmpFinishOutcome, "Approve")
// Set, NOT UpdateContext. A component has no context
// variables at all, so every loc in the original
// overlay became an underscore prefixed global. The
// underscore is the house convention for a global that
// belongs to one component and is not app state.
//
// "Approve" is the OutcomeKey AS STORED, verified
// against a real RequestAssignments row. An earlier
// version emitted "Approved", which compiles, sends
// cleanly and writes a value nothing else in the app
// recognises. The routing panel would have rendered
// every completed task as Not Started.

If(
    _cmpFinishOutcome = "Approve" || IsBlank(_cmpFinishOutcome),
    "",
    "A rejection or a send back has to say why. This is the only explanation the next person sees."
)
// THE RULE STATED WHERE IT BINDS, not only enforced in the
// footer. A disabled button with no reason beside it reads
// as a bug.

If(
    IsBlank(_cmpFinishOutcome)
        || (_cmpFinishOutcome <> "Approve" && IsBlank(Trim(_cmpFinishComment))),
    DisplayMode.Disabled,
    DisplayMode.Edit
)
// A COMMENT IS REQUIRED ON ANYTHING THAT IS NOT AN APPROVAL.
// Trim, because a space is not an explanation. The flow
// validates this again: a disabled button is a courtesy, not
// a control, and the flow is the only thing an attacker
// cannot skip.

cmpDetFinish.OnSubmit()
// RAISES THE EVENT AND NOTHING ELSE. No Patch, no flow call,
// no Navigate. The screen reads OutcomeKey and Comment off the
// instance and calls CompleteAssignment itself.
//
// That boundary is why this component has no dependency on any
// flow, which is what makes it listable on its own and what
// stops a flow rename from being a component edit.
